export function parseInput(rawInput: string): string {
  if (typeof rawInput !== 'string' || rawInput.trim() === '') {
    throw new Error('Input must be a non-empty string');
  }
  return rawInput.trim();
}

// Counts characters and words in the provided text

export function countCharactersAndWords(text: string): { characters: number, words: number } {
  const characterCount = text.length;
  const wordCount = text.trim() === '' ? 0 : text.split(/\s+/).filter(word => word.length > 0).length;

  return {
    characters: characterCount,
    words: wordCount
  };
}

import { parseInput } from './input-parser';
import { countCharactersAndWords } from './counter';

const run = (): void => {
  const args = process.argv.slice(2);
  const userInput = args.join(' ');

  if (userInput === '') {
    console.error('Invalid input. Please provide text as input.');
    return;
  }

  const { characters, words } = countCharactersAndWords(userInput);
  console.log(`Characters: ${characters}`);
  console.log(`Words: ${words}`);
};

run();

